it("keeps unsaved edits when an unrelated agent refresh arrives (LeoPhoneAgent)", async () => {
  // 运行中的智能体会因状态/心跳实时事件被频繁重新获取；这类与保存无关的刷新不能清空未保存的编辑。
  const onSave = vi.fn(async (_patch: Record<string, unknown>) => {});
  const container = document.createElement("div");
  document.body.appendChild(container);
  const root = createRoot(container);
  roots.push(root);
  const queryClient = new QueryClient({
    defaultOptions: { queries: { retry: false }, mutations: { retry: false } },
  });
  let refreshAgent: (agent: Agent) => void = () => {};
  function RefreshHarness() {
    const [agent, setAgent] = useState(() => makeAgent());
    refreshAgent = setAgent;
    return (
      <AgentConfigForm
        mode="edit"
        agent={agent}
        onSave={onSave}
        hidePromptTemplate
        showAdapterTypeField={false}
      />
    );
  }
  await act(async () => {
    root.render(
      <QueryClientProvider client={queryClient}>
        <ToastProvider>
          <TooltipProvider>
            <RefreshHarness />
          </TooltipProvider>
        </ToastProvider>
      </QueryClientProvider>,
    );
  });
  await flushReact();
  const nameInput = () => container.querySelector<HTMLInputElement>('input[placeholder="智能体名称"]')!;
  expect(nameInput()).toBeTruthy();
  setInputValue(nameInput(), "未保存的新名字");
  await flushReact();

  // 与保存无关的刷新（状态/心跳事件导致重新获取）：编辑保留，保存按钮仍在。
  await act(async () => {
    refreshAgent(makeAgent());
  });
  await flushReact();
  expect(nameInput().value).toBe("未保存的新名字");
  const saveButton = findButton(container, "保存");
  expect(saveButton).toBeTruthy();

  // 保存后，带回已保存值的刷新扣除已保存字段，表单回到干净状态。
  await act(async () => {
    saveButton!.click();
  });
  await flushReact();
  expect(onSave).toHaveBeenCalledTimes(1);
  await act(async () => {
    refreshAgent(makeAgent({ name: "未保存的新名字" }));
  });
  await flushReact();
  expect(nameInput().value).toBe("未保存的新名字");
  expect(findButton(container, "保存")).toBeFalsy();
});

